def find_recfun {α β : Type} (n : varN) : List (varN × α × β) → Option (α × β)
  | [] => none
  | (f, x, e) :: rest => if f == n then some (x, e) else find_recfun n rest

-- Use this branch with the binary64 implementation below.
| .FMA, [c, a, b] => some (.inr (.Litv (.Float64 (fmaRNE a b c))))

-- Helpers to place before do_arith. Finite operands are integers in units of 2^-1074.
private def expField (w : UInt64) := w.toNat / 2^52 % 2048
private def fraction (w : UInt64) := w.toNat % 2^52
private def negativeBit (w : UInt64) : Bool := decide (w.toNat ≥ 2^63)
private def finiteUnits (w : UInt64) : Int :=
  let e := expField w
  let m := if e = 0 then fraction w else (2^52 + fraction w) * 2^(e-1)
  if negativeBit w then -(Int.ofNat m) else Int.ofNat m
private def pack64 (neg : Bool) (e f : Nat) : UInt64 :=
  ((if neg then 2^63 else 0) + e * 2^52 + f).toUInt64
private opaque fmaNanChoice : UInt64 → UInt64 → UInt64 → Bool × Fin (2^51)
private def fmaRNE (a b c : UInt64) : UInt64 := Id.run do
  let special := fun w => decide (expField w = 2047)
  let nan := fun w => special w && decide (fraction w ≠ 0)
  let zero := fun (w : UInt64) => decide (w.toNat % 2^63 = 0)
  let prodNeg := negativeBit a != negativeBit b
  let prodInf := special a || special b
  if nan a || nan b || nan c || (special a && zero b) || (special b && zero a) || (prodInf && special c && (prodNeg != negativeBit c)) then
    let (s, p) := fmaNanChoice a b c
    return pack64 s 2047 (2^51 + p.val)
  if prodInf then return pack64 prodNeg 2047 0
  if special c then return c
  let x := finiteUnits a * finiteUnits b + finiteUnits c * (2^1074 : Int)
  if x = 0 then return pack64 (prodNeg && negativeBit c && zero c && (zero a || zero b)) 0 0
  let mag := x.natAbs
  let shift := max 1074 (mag.log2 - 52)
  let unit := 2^shift
  let q := mag / unit
  let twiceRem := 2 * (mag % unit)
  let rounded := if twiceRem > unit ∨ (twiceRem = unit ∧ q % 2 = 1) then q + 1 else q
  let neg := decide (x < 0)
  if rounded < 2^52 then return pack64 neg 0 rounded
  let carry := rounded = 2^53
  let e := shift - 1073 + (if carry then 1 else 0)
  if e ≥ 2047 then return pack64 neg 2047 0
  return pack64 neg e (if carry then 0 else rounded - 2^52)
